const express = require('express');
const crypto = require('crypto');
const { promisify } = require('util');
const argon2 = require('argon2');

const app = express();
app.use(express.json());

// In-memory encrypted storage (simulating encrypted DB)
const encryptedVault = new Map();
const sessionTokens = new Map();
const transferLocks = new Map();

const ENCRYPTION_KEY = crypto.randomBytes(32);
const IV_LENGTH = 16;

function encrypt(text) {
  const iv = crypto.randomBytes(IV_LENGTH);
  const cipher = crypto.createCipheriv('aes-256-gcm', ENCRYPTION_KEY, iv);
  let encrypted = cipher.update(text, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  const authTag = cipher.getAuthTag().toString('hex');
  return iv.toString('hex') + ':' + authTag + ':' + encrypted;
}

function decrypt(encryptedText) {
  const parts = encryptedText.split(':');
  const iv = Buffer.from(parts[0], 'hex');
  const authTag = Buffer.from(parts[1], 'hex');
  const encrypted = parts[2];
  const decipher = crypto.createDecipheriv('aes-256-gcm', ENCRYPTION_KEY, iv);
  decipher.setAuthTag(authTag);
  let decrypted = decipher.update(encrypted, 'hex', 'utf8');
  decrypted += decipher.final('utf8');
  return decrypted;
}

function getBalance(userId) {
  const encData = encryptedVault.get(userId);
  if (!encData) return 0;
  const data = JSON.parse(decrypt(encData));
  return data.balance;
}

function setBalance(userId, newBalance) {
  const encData = encryptedVault.get(userId);
  let data = encData ? JSON.parse(decrypt(encData)) : { balance: 0, history: [] };
  data.balance = newBalance;
  data.history.push({ amount: newBalance, timestamp: Date.now() });
  encryptedVault.set(userId, encrypt(JSON.stringify(data)));
}

async function authenticateRequest(req) {
  const token = req.headers['x-session-token'];
  if (!token) return null;
  const session = sessionTokens.get(token);
  if (!session || session.expiresAt < Date.now()) return null;
  return session.userId;
}

// Acquire a transfer lock with timeout
async function acquireTransferLock(userId, transferId) {
  const lockKey = `transfer:${userId}`;
  const existingLock = transferLocks.get(lockKey);

  if (existingLock && existingLock.expiresAt > Date.now()) {
    return false; // Lock held by another transfer
  }

  // Set lock with 5 second expiry
  transferLocks.set(lockKey, { transferId, expiresAt: Date.now() + 5000 });
  return true;
}

function releaseTransferLock(userId, transferId) {
  const lockKey = `transfer:${userId}`;
  const lock = transferLocks.get(lockKey);
  if (lock && lock.transferId === transferId) {
    transferLocks.delete(lockKey);
  }
}

app.post('/api/register', async (req, res) => {
  const { username, password, initialDeposit } = req.body;
  if (!username || !password) return res.status(400).json({ error: 'Missing fields' });

  const userId = crypto.randomUUID();
  const hashedPassword = await argon2.hash(password);

  const userData = { balance: initialDeposit || 0, history: [] };
  encryptedVault.set(userId, encrypt(JSON.stringify(userData)));
  encryptedVault.set(`cred:${username}`, encrypt(JSON.stringify({ userId, hashedPassword })));

  res.json({ userId, message: 'Registered successfully' });
});

app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;
  const encCred = encryptedVault.get(`cred:${username}`);
  if (!encCred) return res.status(401).json({ error: 'Invalid credentials' });

  const cred = JSON.parse(decrypt(encCred));
  const valid = await argon2.verify(cred.hashedPassword, password);
  if (!valid) return res.status(401).json({ error: 'Invalid credentials' });

  const token = crypto.randomBytes(32).toString('hex');
  sessionTokens.set(token, { userId: cred.userId, expiresAt: Date.now() + 3600000 });
  res.json({ token });
});

app.post('/api/transfer', async (req, res) => {
  const userId = await authenticateRequest(req);
  if (!userId) return res.status(401).json({ error: 'Unauthorized' });

  const { toUserId, amount } = req.body;
  if (!toUserId || !amount || amount <= 0) {
    return res.status(400).json({ error: 'Invalid transfer parameters' });
  }

  const transferId = crypto.randomUUID();
  const lockAcquired = await acquireTransferLock(userId, transferId);

  if (!lockAcquired) {
    return res.status(429).json({ error: 'Transfer in progress, please wait' });
  }

  try {
    // Read current balance
    const currentBalance = getBalance(userId);

    // Simulate async processing (e.g., fraud check, compliance verification)
    await new Promise(resolve => setImmediate(resolve));

    // Verify sufficient funds after async gap
    if (currentBalance < amount) {
      return res.status(400).json({ error: 'Insufficient funds' });
    }

    // Execute transfer
    setBalance(userId, currentBalance - amount);
    const recipientBalance = getBalance(toUserId);
    setBalance(toUserId, recipientBalance + amount);

    res.json({ success: true, transferId, newBalance: currentBalance - amount });
  } finally {
    releaseTransferLock(userId, transferId);
  }
});

app.get('/api/balance', async (req, res) => {
  const userId = await authenticateRequest(req);
  if (!userId) return res.status(401).json({ error: 'Unauthorized' });

  res.json({ balance: getBalance(userId) });
});

module.exports = app;
